    @Test func emptyChallenge() async throws {
        let secretKey = try #require(SecretKey([0xd4, 0x03, 0xa6, 0x4e, 0x3a, 0xc3, 0x10, 0x8b, 0x74, 0x8a, 0x95, 0xe0, 0x40, 0x6d, 0x83, 0xe5, 0xd9, 0x91, 0xff, 0x89, 0x55, 0x3e, 0x9a, 0x76, 0x33, 0x22, 0x19, 0x36, 0xe0, 0x58, 0x4e, 0x9a]))
        let pubkey = secretKey.pubkey
        let blockchain = try await BlockchainService(params: .signet(options: .init(challenge: [])))
        let block1 = try #require(await blockchain.generateTo(Script.payToPubkeyHash(pubkey), initialNonce: 4479814, maxTries: 0, blockTime: .init(timeIntervalSince1970: 1704890713)))
        let blockchain2 = try await BlockchainService(params: .signet(options: .init(challenge: [])))
        try await blockchain2.processBlock(block1, immediate: true)
        let height = await blockchain.height
        #expect(height == 1)
        #expect(await blockchain2.height == height)
    }

    @Test func trivialChallenge() async throws {
        let secretKey = try #require(SecretKey([0xd4, 0x03, 0xa6, 0x4e, 0x3a, 0xc3, 0x10, 0x8b, 0x74, 0x8a, 0x95, 0xe0, 0x40, 0x6d, 0x83, 0xe5, 0xd9, 0x91, 0xff, 0x89, 0x55, 0x3e, 0x9a, 0x76, 0x33, 0x22, 0x19, 0x36, 0xe0, 0x58, 0x4e, 0x9a]))
        let pubkey = secretKey.pubkey
        let challenge = Script([.constant(1)])
        let blockchain = try await BlockchainService(params: .signet(options: .init(challenge: challenge)))
        let block1 = try #require(await blockchain.generateTo(Script.payToPubkeyHash(pubkey), initialNonce: 4479814, maxTries: 0, blockTime: .init(timeIntervalSince1970: 1704890713)))
        let blockchain2 = try await BlockchainService(params: .signet(options: .init(challenge: challenge)))
        try await blockchain2.processBlock(block1, immediate: true)
        let height = await blockchain.height
        #expect(height == 1)
        #expect(await blockchain2.height == height)
    }

    @Test func simplePayToTaprootChallenge() async throws {
        let secretKey = try #require(SecretKey([0xd4, 0x03, 0xa6, 0x4e, 0x3a, 0xc3, 0x10, 0x8b, 0x74, 0x8a, 0x95, 0xe0, 0x40, 0x6d, 0x83, 0xe5, 0xd9, 0x91, 0xff, 0x89, 0x55, 0x3e, 0x9a, 0x76, 0x33, 0x22, 0x19, 0x36, 0xe0, 0x58, 0x4e, 0x9a]))
        let pubkey = secretKey.pubkey // For receiving reward
        let internalKey = secretKey.taprootInternalKey // For the signet challenge
        let challenge = Script.payToTaproot(internalKey: internalKey)
        let blockchain = try await BlockchainService(params: .signet(options: .init(challenge: challenge)))
        let block1 = try #require(await blockchain.generateTo(Script.payToPubkeyHash(pubkey), signetSecretKey: secretKey, initialNonce: 18122174, maxTries: 0, blockTime: .init(timeIntervalSince1970: 1704890713)))
        // print(block1.nonce)
        let blockchain2 = try await BlockchainService(params: .signet(options: .init(challenge: challenge)))
        try await blockchain2.processBlock(block1, immediate: true)
        let height = await blockchain.height
        #expect(height == 1)
        #expect(await blockchain2.height == height)
    }

